def compute_order_amount(age, pipeline, mu, cv, f, L):
    S = 14.5 # OPT_PARAM: {"type":"float","initial":14.5,"min":0.0,"max":60.0}
    C = 16.0 # OPT_PARAM: {"type":"float","initial":16.0,"min":0.0,"max":60.0}
    G = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.1,"max":3.0}
    Q = 0.0 # OPT_PARAM: {"type":"float","initial":0.0,"min":-0.1,"max":0.1}
    KF = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.25,"max":1.75}
    KL = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.25,"max":1.75}
    W0 = 0.0 # OPT_PARAM: {"type":"float","initial":0.0,"min":0.0,"max":1.0}
    A = 0.1 # OPT_PARAM: {"type":"float","initial":0.1,"min":0.01,"max":4.0}
    B = 0.0 # OPT_PARAM: {"type":"float","initial":0.0,"min":-0.9,"max":3.0}
    WP = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.0,"max":2.0}
    R = 0.35 # OPT_PARAM: {"type":"float","initial":0.35,"min":0.0,"max":1.0}

    m = len(age)
    if m <= 0:
        return 0.0

    power = A + 1.8*f
    static_effective = 0.0
    for i in range(m):
        z = (i + 1.0)/m
        core = (z**power)*(1.0 + B*(1.0 - z))
        if core < 0.0:
            core = 0.0
        weight = W0 + (1.0 - W0)*core
        units = age[i]
        if units < 0.0:
            units = 0.0
        static_effective = static_effective + weight*units

    pipeline_total = 0.0
    for j in range(len(pipeline)):
        units = pipeline[j]
        if units > 0.0:
            pipeline_total = pipeline_total + units
    static_effective = static_effective + WP*pipeline_total

    x = [0.0 for i in range(m)]
    for i in range(m):
        units = age[i]
        if units < 0.0:
            units = 0.0
        x[i] = units

    mf = f*mu
    vf = f*(mu*cv)*(mu*cv)
    ml = (1.0 - f)*mu
    vl = (1.0 - f)*(mu*cv)*(mu*cv)

    wf1 = 0.0
    pf1 = 1.0
    pf2 = 1.0
    rf1 = 0.0
    rf2 = 0.0
    if mf > 0.0:
        af = vf/(mf*mf) - 1.0/mf
        if af < 1.0:
            af = 1.0
        discf = af*af - 1.0
        if discf < 0.0:
            discf = 0.0
        bf = 1.0 + af + discf**0.5
        cf = 1.0 + af - discf**0.5
        wf1 = 1.0/bf
        pf1 = 2.0/(2.0 + mf*bf)
        pf2 = 2.0/(2.0 + mf*cf)
        rf1 = 1.0 - pf1
        rf2 = 1.0 - pf2

    wl1 = 0.0
    pl1 = 1.0
    pl2 = 1.0
    rl1 = 0.0
    rl2 = 0.0
    if ml > 0.0:
        al = vl/(ml*ml) - 1.0/ml
        if al < 1.0:
            al = 1.0
        discl = al*al - 1.0
        if discl < 0.0:
            discl = 0.0
        bl = 1.0 + al + discl**0.5
        cl = 1.0 + al - discl**0.5
        wl1 = 1.0/bl
        pl1 = 2.0/(2.0 + ml*bl)
        pl2 = 2.0/(2.0 + ml*cl)
        rl1 = 1.0 - pl1
        rl2 = 1.0 - pl2

    for t in range(L):
        stock = 0.0
        for i in range(m):
            stock = stock + x[i]

        fifo_sales = 0.0
        if mf > 0.0 and stock > 0.0:
            fifo_sales = wf1*rf1*(1.0 - rf1**stock)/pf1
            fifo_sales = fifo_sales + (1.0 - wf1)*rf2*(1.0 - rf2**stock)/pf2
            fifo_sales = KF*fifo_sales
            if fifo_sales > stock:
                fifo_sales = stock
            if fifo_sales < 0.0:
                fifo_sales = 0.0

        remaining = fifo_sales
        for i in range(m):
            take = remaining
            if take > x[i]:
                take = x[i]
            if take < 0.0:
                take = 0.0
            x[i] = x[i] - take
            remaining = remaining - take

        stock = 0.0
        for i in range(m):
            stock = stock + x[i]

        lifo_sales = 0.0
        if ml > 0.0 and stock > 0.0:
            lifo_sales = wl1*rl1*(1.0 - rl1**stock)/pl1
            lifo_sales = lifo_sales + (1.0 - wl1)*rl2*(1.0 - rl2**stock)/pl2
            lifo_sales = KL*lifo_sales
            if lifo_sales > stock:
                lifo_sales = stock
            if lifo_sales < 0.0:
                lifo_sales = 0.0

        remaining = lifo_sales
        for k in range(m):
            i = m - 1 - k
            take = remaining
            if take > x[i]:
                take = x[i]
            if take < 0.0:
                take = 0.0
            x[i] = x[i] - take
            remaining = remaining - take

        for i in range(m - 1):
            x[i] = x[i + 1]
        x[m - 1] = 0.0

        if t < len(pipeline):
            arrival = pipeline[t]
            if arrival > 0.0:
                x[m - 1] = x[m - 1] + arrival

    projected_effective = 0.0
    for i in range(m):
        z = (i + 1.0)/m
        core = (z**power)*(1.0 + B*(1.0 - z))
        if core < 0.0:
            core = 0.0
        weight = W0 + (1.0 - W0)*core
        projected_effective = projected_effective + weight*x[i]

    effective = R*projected_effective + (1.0 - R)*static_effective
    gap = S - effective
    gain = G + Q*gap
    if gain < 0.0:
        gain = 0.0
    if gain > 3.0:
        gain = 3.0

    order = gain*gap
    if order < 0.0:
        order = 0.0
    if order > C:
        order = C
    if order != order:
        order = 0.0
    return float(order)

def compute_order_amount(age, pipeline, mu, cv, f, L):
    S = 15.5 # OPT_PARAM: {"type":"float","initial":15.5,"min":0.0,"max":60.0}
    C = 18.0 # OPT_PARAM: {"type":"float","initial":18.0,"min":0.0,"max":60.0}
    W_DOOM = 0.3 # OPT_PARAM: {"type":"float","initial":0.3,"min":0.0,"max":4.0}
    W_EARLY = 0.3 # OPT_PARAM: {"type":"float","initial":0.3,"min":0.0,"max":4.0}
    W_MID = 0.65 # OPT_PARAM: {"type":"float","initial":0.65,"min":0.0,"max":4.0}
    W_FRESH = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.0,"max":4.0}
    W_PIPE = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.0,"max":4.0}
    K_BLOCK = 0.5 # OPT_PARAM: {"type":"float","initial":0.5,"min":0.0,"max":8.0}

    m = len(age)
    effective = 0.0
    old_risk = 0.0
    young_cover = 0.0

    for i in range(m):
        stock = age[i]
        if i < L:
            effective = effective + W_DOOM * stock
        else:
            denominator = float(max(1, m - L))
            x = float(i + 1 - L) / denominator
            one_minus_x = 1.0 - x
            weight = (W_EARLY * one_minus_x * one_minus_x
                      + 2.0 * W_MID * x * one_minus_x
                      + W_FRESH * x * x)
            effective = effective + weight * stock
            old_risk = old_risk + one_minus_x * stock
            young_cover = young_cover + x * stock

    pipeline_total = 0.0
    for j in range(len(pipeline)):
        pipeline_total = pipeline_total + pipeline[j]

    effective = effective + W_PIPE * pipeline_total
    young_cover = young_cover + pipeline_total

    scale = mu * float(max(1, m))
    blocking = K_BLOCK * max(0.0, 1.0 - f) * old_risk * young_cover / scale
    raw = S - effective - blocking

    if not (raw == raw):
        return 0.0
    if raw <= 0.0:
        return 0.0
    if raw >= C:
        return C
    return raw

def compute_order_amount(age, pipeline, mu, cv, f, L):
    S = 15.0 # OPT_PARAM: {"type":"float","initial":15.0,"min":0.0,"max":60.0}
    C = 18.0 # OPT_PARAM: {"type":"float","initial":18.0,"min":0.0,"max":60.0}
    W0 = 0.15 # OPT_PARAM: {"type":"float","initial":0.15,"min":0.0,"max":2.0}
    W1 = 0.95 # OPT_PARAM: {"type":"float","initial":0.95,"min":0.0,"max":4.0}
    A = 0.9 # OPT_PARAM: {"type":"float","initial":0.9,"min":0.0,"max":6.0}
    P = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.0,"max":3.0}
    B = 0.55 # OPT_PARAM: {"type":"float","initial":0.55,"min":0.0,"max":1.0}
    D = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.25,"max":3.0}

    m = len(age)
    state = [0.0] * m
    for i in range(m):
        x = float(age[i])
        if x < 0.0:
            x = 0.0
        state[i] = x

    for t in range(L):
        for stream in range(2):
            if stream == 0:
                g = f
            else:
                g = 1.0 - f

            if g > 0.0:
                M = g * mu
                V = g * (mu * cv) * (mu * cv)
                da = V / (M * M) - 1.0 / M
                disc = da * da - 1.0
                if disc < 0.0:
                    disc = 0.0
                root = disc ** 0.5
                db = 1.0 + da + root
                dc = 1.0 + da - root
                mix1 = 1.0 / db
                p1 = 2.0 / (2.0 + M * db)
                p2 = 2.0 / (2.0 + M * dc)
                r1 = 1.0 - p1
                r2 = 1.0 - p2
                cumulative = 0.0

                for pos in range(m):
                    if stream == 0:
                        i = pos
                    else:
                        i = m - 1 - pos

                    stock = state[i]
                    upper = cumulative + stock
                    n0 = int(cumulative)
                    n1 = int(upper)
                    frac0 = cumulative - n0
                    frac1 = upper - n1

                    e0r1 = r1 * (1.0 - r1 ** n0) / (1.0 - r1)
                    e0r1 = e0r1 + frac0 * r1 ** (n0 + 1)
                    e1r1 = r1 * (1.0 - r1 ** n1) / (1.0 - r1)
                    e1r1 = e1r1 + frac1 * r1 ** (n1 + 1)

                    e0r2 = r2 * (1.0 - r2 ** n0) / (1.0 - r2)
                    e0r2 = e0r2 + frac0 * r2 ** (n0 + 1)
                    e1r2 = r2 * (1.0 - r2 ** n1) / (1.0 - r2)
                    e1r2 = e1r2 + frac1 * r2 ** (n1 + 1)

                    h0 = mix1 * e0r1 + (1.0 - mix1) * e0r2
                    h1 = mix1 * e1r1 + (1.0 - mix1) * e1r2
                    consumed = D * (h1 - h0)
                    if consumed < 0.0:
                        consumed = 0.0
                    if consumed > stock:
                        consumed = stock

                    state[i] = stock - consumed
                    cumulative = upper

        shifted = [0.0] * m
        for i in range(m - 1):
            shifted[i] = state[i + 1]
        shifted[m - 1] = 0.0
        state = shifted

        if t < L - 1 and t < len(pipeline):
            incoming = float(pipeline[t])
            if incoming > 0.0:
                state[m - 1] = state[m - 1] + incoming

    projected_credit = 0.0
    static_credit = 0.0
    for i in range(m):
        life_fraction = (i + 1.0) / m
        weight = W0 + W1 * life_fraction ** A
        projected_credit = projected_credit + weight * state[i]

        current_stock = float(age[i])
        if current_stock < 0.0:
            current_stock = 0.0
        static_credit = static_credit + weight * current_stock

    pipeline_stock = 0.0
    for j in range(len(pipeline)):
        x = float(pipeline[j])
        if x > 0.0:
            pipeline_stock = pipeline_stock + x
    static_credit = static_credit + P * pipeline_stock

    effective = B * projected_credit + (1.0 - B) * static_credit
    raw = S - effective
    if raw != raw:
        return 0.0
    if raw < 0.0:
        return 0.0
    if raw > C:
        return C
    return raw

def compute_order_amount(age, pipeline, mu, cv, f, L):
    S = 16.0 # OPT_PARAM: {"type":"float","initial":16.0,"min":0.0,"max":60.0}
    C = 18.0 # OPT_PARAM: {"type":"float","initial":18.0,"min":0.0,"max":60.0}
    A = 0.05 # OPT_PARAM: {"type":"float","initial":0.05,"min":0.01,"max":3.0}
    F = 0.02 # OPT_PARAM: {"type":"float","initial":0.02,"min":0.0,"max":0.95}
    B = 0.0 # OPT_PARAM: {"type":"float","initial":0.0,"min":-1.0,"max":3.0}
    P = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.0,"max":2.0}
    G = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.1,"max":2.5}
    K = 0.0 # OPT_PARAM: {"type":"float","initial":0.0,"min":-1.0,"max":2.0}
    m = len(age)
    target = S - 3.4 * (cv - 1.75) - 1.4 * f + 1.0 * (m - 7)
    power = A + 1.8 * f
    effective = 0.0
    old_load = 0.0
    for i in range(m):
        t = (i + 1.0) / m
        weight = F + (1.0 - F) * (t ** power) * (1.0 + B * (1.0 - t))
        effective = effective + weight * age[i]
        old_load = old_load + (1.0 - t) * age[i]
    for j in range(len(pipeline)):
        effective = effective + P * pipeline[j]
    scale = max(1.0, target + mu * m)
    effective = effective + K * old_load * old_load / scale
    gap = target - effective
    order = G * gap
    return max(0.0, min(C, order))

def compute_order_amount(age, pipeline, mu, cv, f, L):
    target = 12.0 # OPT_PARAM: {"type":"float","initial":12.0,"min":0.0,"max":30.0}
    response = 0.75 # OPT_PARAM: {"type":"float","initial":0.75,"min":0.0,"max":3.0}
    demand_factor = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.0,"max":3.0}
    old_credit = 0.25 # OPT_PARAM: {"type":"float","initial":0.25,"min":0.0,"max":1.5}
    age_curve = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.0,"max":5.0}
    order_limit = 12.0 # OPT_PARAM: {"type":"float","initial":12.0,"min":0.0,"max":40.0}
    m = len(age)
    work = [max(0.0, float(age[i])) for i in range(m)]
    demand_scale = demand_factor / max(float(cv), 0.01)
    fifo_forecast = max(0.0, float(mu) * float(f) * demand_scale)
    lifo_forecast = max(0.0, float(mu) * (1.0 - float(f)) * demand_scale)
    for step in range(L):
        fifo_left = fifo_forecast
        for i in range(m):
            used = min(work[i], fifo_left)
            work[i] = work[i] - used
            fifo_left = fifo_left - used
        lifo_left = lifo_forecast
        for i in range(m):
            j = m - 1 - i
            used = min(work[j], lifo_left)
            work[j] = work[j] - used
            lifo_left = lifo_left - used
        shifted = [0.0 for i in range(m)]
        for i in range(m - 1):
            shifted[i] = work[i + 1]
        if step < len(pipeline):
            shifted[m - 1] = max(0.0, float(pipeline[step]))
        work = shifted
    effective = 0.0
    for i in range(m):
        relative_life = float(i + 1) / float(m)
        weight = old_credit + (1.0 - old_credit) * relative_life ** age_curve
        effective = effective + weight * work[i]
    order = response * max(0.0, target - effective)
    return max(0.0, min(order_limit, order))
